-- Registro de modificaciones de una norma (cadena de decretos), con el ESTADO DE VERIFICACIÓN de cada eslabón.
-- Motivo (2026-11-07): la NSR-10 fue modificada por muchos decretos y, al contrastar el Apéndice A-4, hubo que revisar cada anexo
-- a mano; una búsqueda web incluso atribuyó a un «decreto 1166 de 2025» una consolidación que el documento no contiene. Este
-- registro hace explícito qué se verificó contra el texto y qué solo se conoce por referencias o resúmenes.
-- Primera carga: la cadena de la NSR-10. Se espera replicarlo para RAS 2000, manuales INVIAS y demás normas del corpus.

create table if not exists normas_modificaciones (
  id bigint generated by default as identity primary key,
  norma text not null,                         -- p. ej. 'NSR-10'
  decreto text not null,                       -- p. ej. 'Decreto 092 de 2011'
  fecha date,
  diario_oficial text,
  objeto text,
  toca_apendice_a4 text not null default 'no_verificado' check (toca_apendice_a4 in ('si', 'no', 'no_verificado')),
  anexo_obtenido boolean not null default false,
  estado_verificacion text not null check (estado_verificacion in ('texto_verificado', 'solo_citado_por_otro_decreto', 'resumen_web_sin_verificar')),
  fuente_verificacion text,
  verificado_en date not null default current_date,
  unique (norma, decreto)
);

alter table normas_modificaciones enable row level security;
drop policy if exists "lectura publica" on normas_modificaciones;
create policy "lectura publica" on normas_modificaciones for select using (true);

comment on table normas_modificaciones is 'Cadena de decretos que modifican una norma y estado real de verificación de cada uno. No sustituye el texto consolidado oficial.';

insert into normas_modificaciones (norma, decreto, fecha, diario_oficial, objeto, toca_apendice_a4, anexo_obtenido, estado_verificacion, fuente_verificacion) values
  ('NSR-10', 'Decreto 926 de 2010', '2010-03-19', null, 'Adopta el Reglamento NSR-10.', 'si', true, 'solo_citado_por_otro_decreto', 'Citado en el artículo 1 del Decreto 1711 de 2021 (texto leído); el Apéndice A-4 original se ingestó del PDF de la NSR-10.'),
